local game = {name = "Spell Your Bee!", id = 3, done = false, words = {}, wrong = 0, input = "", num = 0, answer = false}

game.words = {
    {word = "door", b64 = ""},
    {word = "cat", b64 = ""},
    {word = "syllabus", b64 = ""},
    {word = "cubitten", b64 = ""},
    {word = "killrlandia", b64 = ""},
    {word = "chromatography", b64 = ""},
    {word = "spritoria", b64 = ""},
    {word = "pneumonoultramicroscopicsilicovolcanoconiosis", b64 = ""},
    {word = "supercalifragilisticexpialidocious", b64 = ""},
    {word = "bee", b64 = ""},
    {word = "python", b64 = ""},
    {word = "june", b64 = ""},
    {word = "compartmentalization", b64 = ""},
    {word = "antidisestablishmentarianism", b64 = ""},
    {word = "Chargoggagoggmanchauggagoggchaubunagungamaugg", b64 = ""}
}


function game.load()
    love.graphics.setBackgroundColor(0, 0.90, 0.90)
end

function game.loop(dt)

    timer = timer + dt

    plrrlp.body:setX(0)
    plrrlp.body:setY(0)

    if not game.answer then
        newspell()
        game.answer = true
    end

    if game.answer then

        if timer > 700 then

            if game.words[game.num].word ~= game.input then
                game.wrong = game.wrong + 1
            end

            game.answer = false
        end
    end
end

function game.draw()
    love.graphics.setColor(0, 0.65, 0)
    love.graphics.rectangle("fill", 0, -150, 300, 50)
end

function game.drawui()
    love.graphics.setColor(1,0,0)

    love.graphics.print(
        "Wrong: " .. game.wrong,
        winw/2 + 1 * pubscale,
        winh/2 + 100 * pubscale,
        0,
        pubscale,
        pubscale
    )
    love.graphics.setColor(0,0,0)
    love.graphics.print(game.input, 0, 100 * pubscale, 0, pubscale, pubscale)
end

function love.textinput(t)
    game.input = game.input .. t
end

function newspell()

    game.num = love.math.random(1, 15)

    game.input = ""

    timer = 0

    love.audio.play(
        loadAudio(
            game.words[game.num].b64,
            "mp3"
        )
    )
end

game.done = true

return game
